1	"use client";
2	
3	import { useState } from "react";
4	import { useRouter } from "next/navigation";
5	import type { EditProductState } from "./actions";
6	
7	export default function EditProductForm({
8	  name,
9	  category,
10	  price,
11	  cost,
12	  minStock,
13	  emoji,
14	  barcode,
15	  sku,
16	  variantLabel,
17	  action,
18	}: {
19	  name: string;
20	  category: string | null;
21	  price: number;
22	  cost: number;
23	  minStock: number;
24	  emoji: string | null;
25	  barcode: string | null;
26	  sku: string | null;
27	  variantLabel: string | null;
28	  action: (state: EditProductState, formData: FormData) => Promise<EditProductState>;
29	}) {
30	  const router = useRouter();
31	  const [open, setOpen] = useState(false);
32	  const [values, setValues] = useState({
33	    name,
34	    category: category ?? "",
35	    price: String(price),
36	    cost: String(cost),
37	    minStock: String(minStock),
38	    emoji: emoji ?? "",
39	    barcode: barcode ?? "",
40	    sku: sku ?? "",
41	    variantLabel: variantLabel ?? "",
42	  });
43	  const [error, setError] = useState<string | null>(null);
44	  const [pending, setPending] = useState(false);
45	
46	  if (!open) {
47	    return (
48	      <button
49	        onClick={() => setOpen(true)}
50	        className="shrink-0 text-xs font-medium text-zinc-400 hover:text-brand-600 hover:underline"
51	      >
52	        Edit
53	      </button>
54	    );
55	  }
56	
57	  async function handleSubmit() {
58	    setError(null);
59	    setPending(true);
60	    const formData = new FormData();
61	    formData.set("name", values.name);
62	    formData.set("category", values.category);
63	    formData.set("price", values.price);
64	    formData.set("cost", values.cost);
65	    formData.set("minStock", values.minStock);
66	    formData.set("emoji", values.emoji);
67	    formData.set("barcode", values.barcode);
68	    formData.set("sku", values.sku);
69	    formData.set("variantLabel", values.variantLabel);
70	    const result = await action({ error: null }, formData);
71	    setPending(false);
72	
73	    if (result.error) {
74	      setError(result.error);
75	      return;
76	    }
77	
78	    setOpen(false);
79	    router.refresh();
80	  }
81	
82	  return (
83	    <div className="mt-2 w-full space-y-2 rounded-xl border border-zinc-200 bg-zinc-50 p-3">
84	      <div>
85	        <label className="mb-1 block text-xs font-medium text-zinc-600">Nama Produk</label>
86	        <input
87	          type="text"
88	          value={values.name}
89	          onChange={(e) => setValues((v) => ({ ...v, name: e.target.value }))}
90	          className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
91	        />
92	      </div>
93	      <div className="grid grid-cols-2 gap-2">
94	        <div>
95	          <label className="mb-1 block text-xs font-medium text-zinc-600">Barcode</label>
96	          <input
97	            type="text"
98	            value={values.barcode}
99	            onChange={(e) => setValues((v) => ({ ...v, barcode: e.target.value }))}
100	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
101	          />
102	        </div>
103	        <div>
104	          <label className="mb-1 block text-xs font-medium text-zinc-600">SKU</label>
105	          <input
106	            type="text"
107	            value={values.sku}
108	            onChange={(e) => setValues((v) => ({ ...v, sku: e.target.value }))}
109	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
110	          />
111	        </div>
112	      </div>
113	      <div>
114	        <label className="mb-1 block text-xs font-medium text-zinc-600">
115	          Varian (mis. Merah / S)
116	        </label>
117	        <input
118	          type="text"
119	          value={values.variantLabel}
120	          onChange={(e) => setValues((v) => ({ ...v, variantLabel: e.target.value }))}
121	          className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
122	        />
123	      </div>
124	      <div className="grid grid-cols-2 gap-2">
125	        <div>
126	          <label className="mb-1 block text-xs font-medium text-zinc-600">Kategori</label>
127	          <input
128	            type="text"
129	            value={values.category}
130	            onChange={(e) => setValues((v) => ({ ...v, category: e.target.value }))}
131	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
132	          />
133	        </div>
134	        <div>
135	          <label className="mb-1 block text-xs font-medium text-zinc-600">Ikon (emoji)</label>
136	          <input
137	            type="text"
138	            maxLength={4}
139	            value={values.emoji}
140	            onChange={(e) => setValues((v) => ({ ...v, emoji: e.target.value }))}
141	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-center text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
142	          />
143	        </div>
144	      </div>
145	      <div className="grid grid-cols-2 gap-2">
146	        <div>
147	          <label className="mb-1 block text-xs font-medium text-zinc-600">Harga Jual</label>
148	          <input
149	            type="number"
150	            min="0"
151	            step="1"
152	            value={values.price}
153	            onChange={(e) => setValues((v) => ({ ...v, price: e.target.value }))}
154	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
155	          />
156	        </div>
157	        <div>
158	          <label className="mb-1 block text-xs font-medium text-zinc-600">Modal (HPP)</label>
159	          <input
160	            type="number"
161	            min="0"
162	            step="1"
163	            value={values.cost}
164	            onChange={(e) => setValues((v) => ({ ...v, cost: e.target.value }))}
165	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
166	          />
167	        </div>
168	      </div>
169	      <div>
170	        <label className="mb-1 block text-xs font-medium text-zinc-600">
171	          Stok Minimum (0 = tanpa notifikasi)
172	        </label>
173	        <input
174	          type="number"
175	          min="0"
176	          step="1"
177	          value={values.minStock}
178	          onChange={(e) => setValues((v) => ({ ...v, minStock: e.target.value }))}
179	          className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
180	        />
181	      </div>
182	
183	      {error && <p className="rounded-lg bg-red-50 px-2 py-1.5 text-xs text-red-600">{error}</p>}
184	
185	      <div className="flex gap-2">
186	        <button
187	          onClick={handleSubmit}
188	          disabled={pending}
189	          className="flex-1 rounded-lg bg-brand-600 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
190	        >
191	          {pending ? "Menyimpan…" : "Simpan"}
192	        </button>
193	        <button
194	          type="button"
195	          onClick={() => {
196	            setOpen(false);
197	            setError(null);
198	          }}
199	          className="rounded-lg px-3 py-2 text-xs font-medium text-zinc-500 hover:text-zinc-700"
200	        >
201	          Batal
202	        </button>
203	      </div>
204	    </div>
205	  );
206	}
