8	export type AddProductState = { error: string | null };
9	
10	export async function addProduct(
11	  businessId: string,
12	  _prevState: AddProductState,
13	  formData: FormData,
14	): Promise<AddProductState> {
15	  const name = (formData.get("name") as string)?.trim();
16	  const category = (formData.get("category") as string)?.trim();
17	  const priceRaw = formData.get("price") as string;
18	  const costRaw = formData.get("cost") as string;
19	  const stockRaw = formData.get("stock") as string;
20	  const minStockRaw = formData.get("minStock") as string;
21	  const emoji = (formData.get("emoji") as string)?.trim();
22	  const barcode = (formData.get("barcode") as string)?.trim();
23	  const sku = (formData.get("sku") as string)?.trim();
24	  const variantLabel = (formData.get("variantLabel") as string)?.trim();
25	
26	  if (!name) {
27	    return { error: "Nama produk wajib diisi." };
28	  }
29	
30	  const price = Number(priceRaw);
31	  if (!priceRaw || Number.isNaN(price) || price < 0) {
32	    return { error: "Harga jual harus angka dan tidak boleh negatif." };
33	  }
34	
35	  const cost = costRaw ? Number(costRaw) : 0;
36	  if (Number.isNaN(cost) || cost < 0) {
37	    return { error: "Modal (HPP) harus angka dan tidak boleh negatif." };
38	  }
39	
40	  const stock = stockRaw ? Number(stockRaw) : 0;
41	  if (Number.isNaN(stock) || stock < 0) {
42	    return { error: "Stok harus angka dan tidak boleh negatif." };
43	  }
44	
45	  const minStock = minStockRaw ? Number(minStockRaw) : 0;
46	  if (Number.isNaN(minStock) || minStock < 0) {
47	    return { error: "Stok minimum harus angka dan tidak boleh negatif." };
48	  }
49	
50	  const supabase = await createClient();
51	  const { error } = await supabase.from("products").insert({
52	    business_id: businessId,
53	    name,
54	    category: category || null,
55	    price,
56	    cost,
57	    stock,
58	    min_stock: minStock,
59	    emoji: emoji || null,
60	    barcode: barcode || null,
61	    sku: sku || null,
62	    variant_label: variantLabel || null,
63	  });
64	
65	  if (error) {
66	    if (error.code === "23505") {
67	      return {
68	        error: error.message.includes("sku")
69	          ? "SKU ini sudah dipakai produk lain."
70	          : "Barcode ini sudah dipakai produk lain.",
71	      };
72	    }
73	    return { error: error.message };
74	  }
75	
76	  await logActivity(
77	    supabase,
78	    businessId,
79	    "produk",
80	    "sukses",
81	    `Produk baru: ${name}`,
82	    `Harga Rp${price.toLocaleString("id-ID")} · stok ${stock}`,
83	  );
84	  revalidatePath(`/business/${businessId}/products`);
85	  return { error: null };
86	}
