112	    return { error: "Harga jual harus angka dan tidak boleh negatif." };
113	  }
114	
115	  const cost = costRaw ? Number(costRaw) : 0;
116	  if (Number.isNaN(cost) || cost < 0) {
117	    return { error: "Modal (HPP) harus angka dan tidak boleh negatif." };
118	  }
119	
120	  const minStock = minStockRaw ? Number(minStockRaw) : 0;
121	  if (Number.isNaN(minStock) || minStock < 0) {
