158	export type AdjustStockResult = { error: string | null };
159	
160	export async function adjustProductStock(
161	  businessId: string,
162	  productId: string,
163	  newStock: number,
164	  reason: string,
165	): Promise<AdjustStockResult> {
166	  if (Number.isNaN(newStock) || newStock < 0) {
167	    return { error: "Stok fisik harus angka dan tidak boleh negatif." };
168	  }
169	  reason = reason.trim();
170	  if (!reason) {
171	    return { error: "Alasan penyesuaian wajib diisi." };
172	  }
173	
174	  const supabase = await createClient();
175	
176	  const { data: product } = await supabase
177	    .from("products")
178	    .select("id, name, stock")
179	    .eq("id", productId)
180	    .eq("business_id", businessId)
181	    .single();
182	
183	  if (!product) {
184	    return { error: "Produk tidak ditemukan." };
185	  }
186	
187	  const stockBefore = Number(product.stock);
188	  const diff = newStock - stockBefore;
189	
190	  if (diff === 0) {
191	    return { error: "Stok fisik sama dengan stok sistem, tidak ada yang disesuaikan." };
192	  }
193	
194	  const { error: updateError } = await supabase
195	    .from("products")
196	    .update({ stock: newStock })
197	    .eq("id", productId);
198	
199	  if (updateError) {
200	    return { error: updateError.message };
201	  }
202	
203	  await supabase.from("stock_adjustments").insert({
204	    business_id: businessId,
205	    product_id: productId,
206	    item_name: product.name,
207	    stock_before: stockBefore,
208	    stock_after: newStock,
209	    diff,
210	    reason,
211	  });
212	
213	  await logActivity(
214	    supabase,
215	    businessId,
216	    "produk",
217	    "warning",
218	    `Penyesuaian stok: ${product.name}`,
219	    `${stockBefore} → ${newStock} (${diff > 0 ? "+" : ""}${diff}) · ${reason}`,
220	  );
221	  revalidatePath(`/business/${businessId}/products`);
222	  return { error: null };
223	}
