225	export async function deleteProduct(businessId: string, productId: string) {
226	  const supabase = await createClient();
227	
228	  const { data: product } = await supabase
229	    .from("products")
230	    .select("name")
231	    .eq("id", productId)
232	    .eq("business_id", businessId)
233	    .maybeSingle();
234	
235	  await supabase
236	    .from("products")
237	    .update({ deleted_at: new Date().toISOString() })
238	    .eq("id", productId)
239	    .eq("business_id", businessId);
240	
241	  if (product) {
242	    await logActivity(supabase, businessId, "produk", "warning", `Produk dihapus: ${product.name}`);
243	  }
244	  revalidatePath(`/business/${businessId}/products`);
245	}
