247	export type ImportProductsState = {
248	  error: string | null;
249	  result: { created: number; updated: number; skipped: number; errors: string[] } | null;
250	};
251	
252	// Matches export/route.ts's column order exactly, so a downloaded-then-
253	// re-uploaded file round-trips without edits.
254	const IMPORT_COLUMNS = [
255	  "name",
256	  "category",
257	  "price",
258	  "cost",
259	  "stock",
260	  "minStock",
261	  "barcode",
262	  "sku",
263	  "variantLabel",
264	  "emoji",
265	] as const;
266	
267	export async function importProducts(
268	  businessId: string,
269	  _prevState: ImportProductsState,
270	  formData: FormData,
271	): Promise<ImportProductsState> {
272	  const file = formData.get("file") as File | null;
273	  if (!file || file.size === 0) {
274	    return { error: "Pilih file CSV dulu.", result: null };
275	  }
276	
277	  const text = await file.text();
278	  const rows = parseCsv(text).filter((r) => r.some((c) => c.trim() !== ""));
279	  if (rows.length < 2) {
280	    return { error: "File CSV kosong atau cuma berisi header.", result: null };
281	  }
282	
283	  const dataRows = rows.slice(1);
284	  const supabase = await createClient();
285	
286	  const { data: existing } = await supabase
287	    .from("products")
288	    .select("id, sku, barcode")
289	    .eq("business_id", businessId)
290	    .is("deleted_at", null);
291	
292	  const bySku = new Map(
293	    (existing ?? []).filter((p) => p.sku).map((p) => [p.sku as string, p.id]),
294	  );
295	  const byBarcode = new Map(
296	    (existing ?? []).filter((p) => p.barcode).map((p) => [p.barcode as string, p.id]),
297	  );
298	
299	  let created = 0;
300	  let updated = 0;
301	  let skipped = 0;
302	  const errors: string[] = [];
303	
304	  for (let i = 0; i < dataRows.length; i++) {
305	    const row = dataRows[i];
306	    const line = i + 2; // +1 for header, +1 for 1-indexing
307	    const get = (col: (typeof IMPORT_COLUMNS)[number]) =>
308	      row[IMPORT_COLUMNS.indexOf(col)]?.trim() || "";
309	
310	    const name = get("name");
311	    if (!name) {
312	      skipped++;
313	      errors.push(`Baris ${line}: nama produk kosong`);
314	      continue;
315	    }
316	    const price = Number(get("price"));
317	    if (get("price") === "" || Number.isNaN(price) || price < 0) {
318	      skipped++;
319	      errors.push(`Baris ${line}: harga jual tidak valid`);
320	      continue;
321	    }
322	    const cost = Number(get("cost")) || 0;
323	    const stock = Number(get("stock")) || 0;
324	    const minStock = Number(get("minStock")) || 0;
325	    const category = get("category") || null;
326	    const barcode = get("barcode") || null;
327	    const sku = get("sku") || null;
328	    const variantLabel = get("variantLabel") || null;
329	    const emoji = get("emoji") || null;
330	
331	    const record = {
332	      name,
333	      category,
334	      price,
335	      cost,
336	      stock,
337	      min_stock: minStock,
338	      barcode,
339	      sku,
340	      variant_label: variantLabel,
341	      emoji,
342	    };
343	
344	    const matchId = (sku && bySku.get(sku)) || (barcode && byBarcode.get(barcode)) || null;
345	
346	    if (matchId) {
347	      const { error } = await supabase
348	        .from("products")
349	        .update(record)
350	        .eq("id", matchId)
351	        .eq("business_id", businessId);
352	      if (error) {
353	        skipped++;
354	        errors.push(`Baris ${line}: ${error.message}`);
355	      } else {
356	        updated++;
357	      }
358	    } else {
359	      const { error } = await supabase
360	        .from("products")
361	        .insert({ business_id: businessId, ...record });
362	      if (error) {
363	        skipped++;
364	        errors.push(`Baris ${line}: ${error.message}`);
365	      } else {
366	        created++;
367	      }
368	    }
369	  }
370	
371	  await logActivity(
372	    supabase,
373	    businessId,
374	    "produk",
375	    skipped > 0 ? "warning" : "sukses",
376	    `Impor CSV produk: ${created} baru, ${updated} diperbarui, ${skipped} dilewati`,
377	  );
378	  revalidatePath(`/business/${businessId}/products`);
379	  return { error: null, result: { created, updated, skipped, errors: errors.slice(0, 20) } };
380	}
