464	  async function handleConfirmPayment() {
465	    setError(null);
466	
467	    if (paymentMethod === "Tunai" && receivedAmount < total) {
468	      setError("Uang diterima kurang dari total belanja.");
469	      return;
470	    }
471	
472	    setSubmitting(true);
473	
474	    const itemsPayload = cart.map((i) => ({
475	      productId: i.productId,
476	      qty: i.qty,
477	      disc: i.disc,
478	      discType: i.discType,
479	    }));
480	    const receivedForCheckout = paymentMethod === "Tunai" ? receivedAmount : total;
481	    const clientRef = crypto.randomUUID();
482	
483	    let result: CheckoutResult;
484	    try {
485	      result = await withTimeout(
486	        checkout(
487	          businessId,
488	          cashierId,
489	          itemsPayload,
490	          paymentMethod,
491	          receivedForCheckout,
492	          orderDisc,
493	          orderDiscType,
494	          selectedCustomer?.id ?? null,
495	          cartOrderIds,
496	          clientRef,
497	        ),
498	        10000,
499	      );
500	    } catch {
501	      // Jaringan bermasalah (fetch gagal total / macet >10 detik) — simpan
502	      // ke antrian offline dan tetap tampilkan sukses ke kasir. clientRef
503	      // yang sama menjamin retry lewat antrian tidak membuat transaksi
504	      // duplikat kalaupun request asli ternyata belakangan tetap sukses.
505	      await enqueueSale({
506	        clientRef,
507	        businessId,
508	        kind: "retail",
509	        createdAt: new Date().toISOString(),
510	        status: "pending",
511	        payload: {
512	          cashierId,
513	          items: itemsPayload,
514	          paymentMethod,
515	          received: receivedForCheckout,
516	          orderDisc,
517	          orderDiscType,
518	          customerId: selectedCustomer?.id ?? null,
519	          selfOrderIds: cartOrderIds,
520	        },
521	      });
522	
523	      setSubmitting(false);
524	      setSuccessOffline(true);
525	      setSuccessInvoice(`OFFLINE-${clientRef.slice(0, 8).toUpperCase()}`);
526	      setSuccessTransactionId(null);
527	      setCart([]);
528	      setCartOrderIds([]);
529	      setPaying(false);
530	      setReceived("");
531	      setOrderDisc(0);
532	      setOrderDiscType("pct");
533	      setOrderDiscOpen(false);
534	      setEditingDiscId(null);
535	      setSelectedCustomer(null);
536	      setCustomerPickerOpen(false);
537	      setCustomerSearch("");
538	      void syncNow();
539	      return;
540	    }
541	    setSubmitting(false);
542	
543	    if (!result.success) {
544	      setError(result.error);
545	      return;
546	    }
