1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { logActivity } from "@/lib/activity-log";
5	
6	export type ManualTransactionItemInput = { productId: string; qty: number };
7	
8	export type CreateManualTransactionResult =
9	  | { success: true; transactionId: string; invoiceNumber: string }
10	  | { success: false; error: string };
11	
12	export async function createManualTransaction(
13	  businessId: string,
14	  date: string,
15	  items: ManualTransactionItemInput[],
16	  paymentMethod: string,
17	  received: number | null,
18	  customerId: string | null,
19	): Promise<CreateManualTransactionResult> {
20	  if (items.length === 0) {
21	    return { success: false, error: "Keranjang masih kosong." };
22	  }
23	
24	  const supabase = await createClient();
25	  const { data, error } = await supabase
26	    .rpc("create_manual_transaction", {
27	      p_business_id: businessId,
28	      p_date: date,
29	      p_items: items.map((i) => ({ product_id: i.productId, qty: i.qty })),
30	      p_payment_method: paymentMethod,
31	      p_received: received,
32	      p_customer_id: customerId,
33	    })
34	    .single();
35	
36	  if (error || !data) {
37	    return { success: false, error: error?.message ?? "Gagal menyimpan transaksi." };
38	  }
39	
40	  const result = data as { transaction_id: string; invoice_number: string };
41	
42	  const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
43	  await logActivity(
44	    supabase,
45	    businessId,
46	    "transaksi",
47	    "info",
48	    `Transaksi manual ${result.invoice_number}`,
49	    `${itemCount} item · ${paymentMethod}`,
50	  );
51	
52	  return {
53	    success: true,
54	    transactionId: result.transaction_id,
55	    invoiceNumber: result.invoice_number,
56	  };
57	}
