7	function formatRupiah(value: number) {
8	  return `Rp${value.toLocaleString("id-ID")}`;
9	}
10	
11	function formatDateTime(iso: string) {
12	  return new Date(iso).toLocaleString("id-ID", {
13	    day: "2-digit",
14	    month: "short",
15	    hour: "2-digit",
16	    minute: "2-digit",
17	  });
18	}
