20	export default async function TransactionsPage({
21	  params,
22	}: {
23	  params: Promise<{ businessId: string }>;
24	}) {
25	  const { businessId } = await params;
26	  const supabase = await createClient();
27	
28	  const { data: business } = await supabase
29	    .from("businesses")
30	    .select("id, name")
31	    .eq("id", businessId)
32	    .single();
33	
34	  if (!business) {
