42	    )
43	    .eq("business_id", businessId)
44	    .order("date", { ascending: false })
45	    .limit(50);
46	
47	  const boundImportTransactions = importTransactions.bind(null, businessId);
48	
49	  return (
50	    <div className="w-full max-w-2xl">
51	        <div className="flex flex-wrap items-start justify-between gap-3">
