56	            <p className="mt-1 text-sm text-zinc-500">50 transaksi terbaru.</p>
57	          </div>
58	          <TransactionButtons businessId={businessId} />
59	        </div>
60	
61	        <TransactionImportCard importAction={boundImportTransactions} />
62	
63	        <div className="mt-6 space-y-2">
64	          {transactions && transactions.length > 0 ? (
65	            transactions.map((t) => (
66	              <Link
67	                key={t.id}
68	                href={`/business/${businessId}/transactions/${t.id}`}
69	                className="block rounded-xl border border-zinc-200 bg-white px-4 py-3 transition-colors hover:border-brand-300"
70	              >
71	                <div className="flex items-center justify-between">
72	                  <p className="text-xs font-semibold text-zinc-900">{t.invoice_number}</p>
73	                  {t.voided ? (
74	                    <span className="rounded-full bg-red-50 px-2 py-0.5 text-[10px] font-medium text-red-600">
