84	                  {formatDateTime(t.date)} ·{" "}
85	                  {(t.cashiers as unknown as { name: string } | null)?.name ?? "—"} ·{" "}
86	                  {t.transaction_payments?.[0]?.method ?? "—"}
87	                </p>
88	              </Link>
89	            ))
90	          ) : (
91	            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
92	              Belum ada transaksi.
93	            </p>
